using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata;

namespace PhenX.EntityFrameworkCore.BulkInsert.Metadata;

/// <summary>
/// Shared helpers for reasoning about entity properties.
/// </summary>
internal static class PropertyHelpers
{
    /// <summary>
    /// Determines whether a property's value is generated by the database (identity/sequence/default/computed)
    /// as opposed to being generated on the client (e.g. a Guid value generator with <c>ValueGeneratedOnAdd</c>).
    /// <para>
    /// This is the single source of truth reconciled with issue #105: a property is considered
    /// database-generated only when it is store-generated AND it does not carry a client-side value
    /// (Guid value generators produce their value on the client before the row reaches the database).
    /// </para>
    /// </summary>
    public static bool IsDatabaseGenerated(IProperty property)
    {
        return property.ValueGenerated != ValueGenerated.Never
               && (property.GetDefaultValueSql() != null
                   || property.GetComputedColumnSql() != null
                   || property.FindAnnotation(RelationalAnnotationNames.DefaultValue) != null
                   || (property.ClrType != typeof(Guid) && property.ClrType != typeof(Guid?)));
    }
}
